/**
 * At most one absence per member per workspace. The window is inclusive of
 * `starts_at` and exclusive of `ends_at`.
 */
export const memberAbsences = sqliteTable(
  "member_absences",
  {
    ...tenantColumns,
    userId: text("user_id").notNull(),
    delegateUserId: text("delegate_user_id"),
    startsAt: text("starts_at").notNull(),
    endsAt: text("ends_at").notNull(),
    note: text("note"),
  },
  (table) => [
    primaryKey({ columns: [table.orgId, table.userId] }),
    index("member_absences_org_delegate_idx").on(table.orgId, table.delegateUserId),
  ],
);

export type MemberRow = typeof members.$inferSelect;
export type NewMemberRow = typeof members.$inferInsert;
export type InvitationRow = typeof invitations.$inferSelect;
export type MemberAbsenceRow = typeof memberAbsences.$inferSelect;

