  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

  // The leaver's window goes with them, and nobody may still point at them.
  await absenceRepo.deleteAbsence(input.orgId, removed.userId);
  await absenceRepo.clearDelegate(input.orgId, removed.userId);

  await emit("member.removed", {
    ...actorEnvelope(actor),
    memberId: removed.id,
    userId: removed.userId,
  });

  return removed;
}

/**
 * The stand-in who should receive work for `userId` at `at`, or null when
 * they are not away or named nobody. Delegation does not chain: a delegate
 * who is themselves away is still the one returned.
 */
export async function activeDelegateFor(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (!absence || !isAwayAt(absence, at) || absence.delegateUserId === null) {
    return null;
  }

  const delegate = await memberRepo.findMember(orgId, absence.delegateUserId);
  if (!delegate || delegate.status !== "active") return null;
  return absence.delegateUserId;
}

/**
 * Stores an out-of-office window, replacing any window already stored for
 * this member in this workspace. The end must be strictly after the start.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);
  const member = await requireActiveMember(input.orgId, input.userId);
  assertCan(actor, "member:set_absence", memberResource(member));

  const delegateUserId = input.delegateUserId ?? null;
  if (delegateUserId !== null) {
    if (delegateUserId === input.userId) {
      throw new Error("A member cannot delegate their absence to themselves");
    }
    await requireActiveMember(input.orgId, delegateUserId);
  }

  assertWindowOpen(input.startsAt, input.endsAt);

  return absenceRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note ?? null,
  });
}

/** Removes the stored window. Doing so when none is set is fine. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const member = await requireActiveMember(orgId, userId);
  assertCan(actor, "member:set_absence", memberResource(member));
  await absenceRepo.deleteAbsence(orgId, userId);
}

/**
 * The stored window when it has not ended yet, including one that has not
 * started. Null once it has ended, or when none is set.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  await requireActiveMember(orgId, userId);
  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (!absence) return null;
  if (new Date(absence.endsAt).getTime() <= Date.now()) return null;
  return absence;
}

async function requireActiveMember(orgId: OrgId, userId: UserId): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

/** Inclusive start, exclusive end. */
function isAwayAt(absence: MemberAbsence, at: Date): boolean {
  const t = at.getTime();
  return (
    t >= new Date(absence.startsAt).getTime() &&
    t < new Date(absence.endsAt).getTime()
  );
}

function assertWindowOpen(startsAt: string, endsAt: string): void {
  const start = new Date(startsAt).getTime();
  const end = new Date(endsAt).getTime();
  if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) {
    throw new Error("Absence must end after it starts");
  }
}

