/**
 * The stand-in who should receive work for `userId` at `at`, or null when
 * they are not away or named nobody. Delegation does not chain: a delegate
 * who is themselves away is still the one returned.
 */
export async function activeDelegateFor(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (!absence || !isAwayAt(absence, at) || absence.delegateUserId === null) {
    return null;
