    assigneeId,
  });

  return after;
}

/**
 * New work aimed at someone who is away lands on their delegate instead.
 * Taking the issue yourself is not redirected, and a delegate who is also
 * away keeps it — delegation never chains.
 */
async function assigneeAfterAbsence(
  actor: Actor,
  orgId: OrgId,
  assigneeId: UserId | null,
): Promise<UserId | null> {
  if (assigneeId === null || assigneeId === actor.userId) return assigneeId;
  const delegate = await activeDelegateFor(orgId, assigneeId, new Date());
  return delegate ?? assigneeId;
}

