input.new_string:
subscribe("issue.overdue", async (payload) => {
  if (payload.assigneeId === null) return;
  // The sweep's clock, not wall time: the job announces with its own `now`.
  const delegate = await activeDelegateFor(
    payload.orgId,
    payload.assigneeId,
    new Date(payload.occurredAt),
  );
  await notify(
    payload.orgId,
    "issue_overdue",
    [delegate ?? payload.assigneeId],
    {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: `/issues/${payload.issueId}`,
      actorId: null,
    },
  );
});

