if (payload.mentionedUserIds.length > 0) {
  await notify(
    payload.orgId,
    "comment_mention",
    payload.mentionedUserIds,
    {
      title: "You were mentioned",
      body: `You were mentioned on issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    },
  );
}

input.new_string:
if (payload.mentionedUserIds.length > 0) {
  // One notify() call so a delegate who is also mentioned directly still
  // receives a single mention alert. A second call would duplicate it.
  const recipients = await mentionRecipients(
    payload.orgId,
    payload.mentionedUserIds,
    new Date(payload.occurredAt),
  );
  await notify(payload.orgId, "comment_mention", recipients, {
    title: "You were mentioned",
    body: `You were mentioned on issue ${payload.issueId}`,
    href: `/issues/${payload.issueId}`,
    actorId: payload.actorId,
  });
}

/**
 * Mention alerts go to each named person and, when they are away, their
 * delegate as well. Preferences and the author's exclusion still happen
 * inside `notify`.
 */
async function mentionRecipients(
  orgId: OrgId,
  mentionedUserIds: readonly UserId[],
  at: Date,
): Promise<UserId[]> {
  const recipients: UserId[] = [];
  for (const userId of mentionedUserIds) {
    recipients.push(userId);
    const delegate = await activeDelegateFor(orgId, userId, at);
    if (delegate !== null) recipients.push(delegate);
  }
  return recipients;
}

