/**
 * Temporary coverage for out-of-office. Deleted after the behavior is checked.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { can } from "@/lib/permissions";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { issueResource, NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { setAbsenceSchema } from "@/schemas/member";
import { toIsoTimestamp } from "@/types/common";
import type { CommentId, UserId } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Actor } from "@/types/member";

const NOW = new Date("2026-06-01T12:00:00.000Z");
const START = toIsoTimestamp(new Date("2026-06-01T00:00:00.000Z"));
const END = toIsoTimestamp(new Date("2026-06-02T00:00:00.000Z"));

let cleanup: () => void;

beforeAll(async () => {
  vi.useFakeTimers();
  vi.setSystemTime(NOW);
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});

afterAll(() => {
  vi.useRealTimers();
  cleanup();
});

function window(
  tenant: Tenant,
  userId: UserId,
  overrides: Partial<{
    delegateUserId: UserId | null;
    startsAt: string;
    endsAt: string;
    note: string | null;
  }> = {},
) {
  return setAbsenceSchema.parse({
    orgId: tenant.org.id,
    userId,
    delegateUserId: overrides.delegateUserId ?? null,
    startsAt: overrides.startsAt ?? START,
    endsAt: overrides.endsAt ?? END,
    note: overrides.note ?? null,
  });
}

async function mentions(tenant: Tenant, recipientId: UserId) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: ["comment_mention"],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

async function assigned(tenant: Tenant, recipientId: UserId) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: ["issue_assigned"],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

async function overdue(tenant: Tenant, recipientId: UserId) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: ["issue_overdue"],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

describe("out of office", () => {
  it("lets a member set, replace and clear their own absence", async () => {
    const tenant = await createTenant("ooo-own");
    const first = await memberService.setAbsence(
      tenant.actors.member,
      window(tenant, tenant.userIds.member, { note: "away" }),
    );
    expect(first).toMatchObject({
      userId: tenant.userIds.member,
      delegateUserId: null,
      note: "away",
      startsAt: START,
      endsAt: END,
    });

    const replaced = await memberService.setAbsence(
      tenant.actors.member,
      window(tenant, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
        note: "later",
      }),
    );
    expect(replaced.delegateUserId).toBe(tenant.userIds.admin);
    expect(replaced.note).toBe("later");
    expect(await memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member)).toEqual(replaced);

    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    expect(await memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member)).toBeNull();
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
  });

  it("lets role-changers set anyone's absence and no one else", async () => {
    const tenant = await createTenant("ooo-perm");
    await expect(
      memberService.setAbsence(tenant.actors.member, window(tenant, tenant.userIds.admin)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      memberService.clearAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.admin),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const stored = await memberService.setAbsence(
      tenant.actors.admin,
      window(tenant, tenant.userIds.viewer, { note: "by admin" }),
    );
    expect(stored.userId).toBe(tenant.userIds.viewer);
    await memberService.clearAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer);
  });

  it("rejects a bad window, self-delegate, removed people and other tenants", async () => {
    const tenant = await createTenant("ooo-valid");
    const other = await createTenant("ooo-valid-other");

    await expect(
      memberService.setAbsence(
        tenant.actors.owner,
        window(tenant, tenant.userIds.member, { startsAt: END, endsAt: START }),
      ),
    ).rejects.toThrow(/end after/);
    await expect(
      memberService.setAbsence(
        tenant.actors.owner,
        window(tenant, tenant.userIds.member, { startsAt: START, endsAt: START }),
      ),
    ).rejects.toThrow(/end after/);
    await expect(
      memberService.setAbsence(
        tenant.actors.owner,
        window(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.member }),
      ),
    ).rejects.toThrow(/themselves/);

    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!member) throw new Error("missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });
    await expect(
      memberService.setAbsence(tenant.actors.owner, window(tenant, tenant.userIds.member)),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.setAbsence(
        tenant.actors.owner,
        window(tenant, tenant.userIds.admin, { delegateUserId: tenant.userIds.member }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
