async function emitComment(
  tenant: Tenant,
  issueId: string,
  actor: Actor,
  mentionedUserIds: readonly UserId[],
): Promise<void> {
  const { emit } = await import("@/lib/event-bus");
  await emit("comment.created", {
    orgId: tenant.org.id,
    actorId: actor.userId,
    occurredAt: toIsoTimestamp(NOW),
    commentId: `cmt-${mentionedUserIds.join("-")}-${Math.random()}` as CommentId,
    issueId: issueId as never,
    mentionedUserIds,
  });
}

