function window(
  tenant: Tenant,
  userId: UserId,
  overrides: Partial<{
    delegateUserId: UserId | null;
    startsAt: string;
    endsAt: string;
    note: string | null;
  }> = {},
) {
  return setAbsenceSchema.parse({
    orgId: tenant.org.id,
    userId,
    delegateUserId: overrides.delegateUserId ?? null,
    startsAt: overrides.startsAt ?? START,
    endsAt: overrides.endsAt ?? END,
    note: overrides.note ?? null,
  });
}

async function mentions(tenant: Tenant, recipientId: UserId) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: ["comment_mention"],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

async function assigned(tenant: Tenant, recipientId: UserId) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: ["issue_assigned"],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

async function overdue(tenant: Tenant, recipientId: UserId) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: ["issue_overdue"],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

