      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });
    expect(lastSecond.assigneeId).toBe(tenant.userIds.admin);

    await memberService.setAbsence(
      tenant.actors.owner,
      window(tenant, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
        startsAt: toIsoTimestamp(new Date("2026-05-01T00:00:00.000Z")),
        endsAt: toIsoTimestamp(NOW),
      }),
    );
    const atEnd = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });
    expect(atEnd.assigneeId).toBe(tenant.userIds.member);
  });

  it("sends overdue alerts to the delegate only while one is set", async () => {
    const tenant = await createTenant("ooo-overdue");
    await usageRepo.recomputeUsage(tenant.org.id);
    await memberService.setAbsence(
      tenant.actors.owner,
      window(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.admin }),
    );
    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late",
        assigneeId: tenant.userIds.member,
        dueAt: "2026-01-01T00:00:00.000Z",
      }),
      tenant.userIds.owner,
      number,
    );
    resetOverdueTracking();
    await runOverdueIssueJob(NOW);
    expect(await overdue(tenant, tenant.userIds.admin)).toHaveLength(1);
    expect(await overdue(tenant, tenant.userIds.member)).toHaveLength(0);

    await memberService.setAbsence(
      tenant.actors.owner,
      window(tenant, tenant.userIds.admin, { delegateUserId: null }),
    );
    const number2 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const second = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late alone",
        assigneeId: tenant.userIds.admin,
        dueAt: "2026-01-01T00:00:00.000Z",
      }),
      tenant.userIds.owner,
      number2,
    );
    resetOverdueTracking();
    await runOverdueIssueJob(NOW);
    const adminOverdue = await overdue(tenant, tenant.userIds.admin);
    expect(adminOverdue.some((row) => row.href === `/issues/${second.id}`)).toBe(true);
  });

  it("mentions the member and the delegate once, and stops after the window", async () => {
    const tenant = await createTenant("ooo-mention");
    await memberService.setAbsence(
      tenant.actors.owner,
      window(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.viewer }),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Talk" }),
    );
    await emitComment(tenant, issue.id, tenant.actors.admin, [tenant.userIds.member]);
    expect(await mentions(tenant, tenant.userIds.member)).toHaveLength(1);
    expect(await mentions(tenant, tenant.userIds.viewer)).toHaveLength(1);

    await emitComment(tenant, issue.id, tenant.actors.admin, [
      tenant.userIds.member,
      tenant.userIds.viewer,
    ]);
    expect(await mentions(tenant, tenant.userIds.viewer)).toHaveLength(2);

    await emitComment(tenant, issue.id, tenant.actors.viewer, [tenant.userIds.member]);
    expect(await mentions(tenant, tenant.userIds.viewer)).toHaveLength(2);
    expect(await mentions(tenant, tenant.userIds.member)).toHaveLength(2);

    await memberService.setAbsence(
      tenant.actors.owner,
      window(tenant, tenant.userIds.member, {
        delegateUserId: tenant.userIds.viewer,
        startsAt: toIsoTimestamp(new Date("2026-05-01T00:00:00.000Z")),
        endsAt: toIsoTimestamp(NOW),
      }),
    );
    await emitComment(tenant, issue.id, tenant.actors.admin, [tenant.userIds.member]);
    expect(await mentions(tenant, tenant.userIds.member)).toHaveLength(3);
    expect(await mentions(tenant, tenant.userIds.viewer)).toHaveLength(2);
  });

  it("drops an absence when its member leaves and drops a delegate who leaves", async () => {
    const tenant = await createTenant("ooo-leave");
    await memberService.setAbsence(
      tenant.actors.owner,
      window(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.admin }),
    );
    await memberService.setAbsence(
      tenant.actors.owner,
      window(tenant, tenant.userIds.viewer, { delegateUserId: tenant.userIds.member }),
    );

    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!admin) throw new Error("missing admin");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
    });
    const stayed = await memberService.getAbsence(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(stayed?.delegateUserId).toBeNull();

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "No stand-in",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.member);

    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!member) throw new Error("missing member");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });
    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);
    const viewerAbsence = await memberService.getAbsence(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );
    expect(viewerAbsence?.delegateUserId).toBeNull();
  });

  it("keeps an absence inside the workspace it was set in", async () => {
    const north = await createTenant("ooo-north");
    const south = await createTenant("ooo-south");
    await memberRepo.insertMember(south.org.id, north.userIds.member, "member", null);
    await memberRepo.insertMember(south.org.id, north.userIds.admin, "admin", null);
    const southActor: Actor = {
      userId: north.userIds.member,
      orgId: south.org.id,
      role: "member",
    };
    await memberService.setAbsence(
      north.actors.owner,
      window(north, north.userIds.member, { delegateUserId: north.userIds.admin }),
    );

    const southIssue = await issueService.createIssue(
      { userId: north.userIds.admin, orgId: south.org.id, role: "admin" },
      issueInput(south.org.id, south.project.id, {
        title: "South",
        assigneeId: north.userIds.member,
      }),
    );
    expect(southIssue.assigneeId).toBe(north.userIds.member);
    expect(
      await memberService.getAbsence(southActor, south.org.id, north.userIds.member),
    ).toBeNull();
    expect(
      await memberService.getAbsence(north.actors.owner, north.org.id, north.userIds.member),
    ).not.toBeNull();
  });
});

async function emitComment(
  tenant: Tenant,
  issueId: string,
  actor: Actor,
  mentionedUserIds: readonly UserId[],
): Promise<void> {
  const { emit } = await import("@/lib/event-bus");
  await emit("comment.created", {
    orgId: tenant.org.id,
    actorId: actor.userId,
    occurredAt: toIsoTimestamp(NOW),
    commentId: `cmt-${mentionedUserIds.join("-")}-${Math.random()}` as CommentId,
    issueId: issueId as never,
    mentionedUserIds,
  });
}
